25	namespace atb {
26	static const int32_t IN_TENSOR_NUM = 1;
27	static const int32_t OUT_TENSOR_NUM = 1;
28	static const int32_t IN_TENSOR_NUM_WITH_QUANT = 3;
29	
30	Status CheckAllReduceQuantParam(const infer::AllReduceParam &opParam)
31	{
32	    if (opParam.backend == "lccl" && opParam.quantType != atb::infer::AllReduceParam::QUANT_TYPE_UNQUANT &&
33	        opParam.allReduceType != "sum") {
34	        ATB_LOG(ERROR) << "allReduceType is " << opParam.allReduceType << "AllReduce Quant allReduceType must be sum";
35	        return ERROR_INVALID_PARAM;
36	    }
37	    if (opParam.backend == "hccl" && opParam.quantType != atb::infer::AllReduceParam::QUANT_TYPE_UNQUANT) {
38	        ATB_LOG(ERROR) << "quantType: " << opParam.quantType << "  Hccl is not support quant";
39	        return ERROR_INVALID_PARAM;
40	    }
41	    if (opParam.outDataType != ACL_FLOAT16 && opParam.quantType != atb::infer::AllReduceParam::QUANT_TYPE_UNQUANT) {
42	        ATB_LOG(ERROR) << "outDataType: " << opParam.outDataType << " is not support quant";
43	        return ERROR_INVALID_PARAM;
44	    }
45	    if (opParam.backend == "lccl" && (opParam.quantType < atb::infer::AllReduceParam::QUANT_TYPE_UNQUANT ||
46	                                      opParam.quantType >= atb::infer::AllReduceParam::QUANT_TYPE_MAX)) {
47	        ATB_LOG(ERROR) << "quantType: " << opParam.quantType << " is invalid QuantType";
48	        return ERROR_INVALID_PARAM;
49	    }
50	    return NO_ERROR;
51	}
52	
53	Status CheckAllReduceParamValidity(const infer::AllReduceParam &opParam)
54	{
55	    if (CheckAllReduceQuantParam(opParam) != NO_ERROR) {
56	        return ERROR_INVALID_PARAM;
57	    }
58	    if (opParam.backend != "hccl" && opParam.backend != "lccl") {
59	        ATB_LOG(ERROR) << "backend is " << opParam.backend << "backend must either be hccl or lccl";
60	        return ERROR_INVALID_PARAM;
61	    }
62	    if (opParam.backend == "lccl" && GetSingleton<Config>().Is310P()) {
63	        ATB_LOG(ERROR) << "AllReduce lccl is not support in Atlas inference products";
64	        return ERROR_INVALID_PARAM;
65	    }
66	    if (Mki::PlatformInfo::Instance().GetPlatformType() == Mki::PlatformType::ASCEND_950) {
67	        if (opParam.backend != "hccl") {
68	            ATB_LOG(ERROR) << "At 950, backend only supports hccl, now backend is: " << opParam.backend;
69	            return ERROR_INVALID_PARAM;
70	        }
71	        if (opParam.allReduceType == "prod") {
72	            ATB_LOG(ERROR) << "At 950, allReduceType prod is not supported";
73	            return ERROR_INVALID_PARAM;
74	        }
75	    }
76	    if (OperationUtil::DistributedInitCheck<infer::AllReduceParam>(opParam) != NO_ERROR) {
77	        ATB_LOG(ERROR) << "AllReduceOperation DistributedInitCheck failed";
78	        return ERROR_INVALID_PARAM;
79	    }
80	    if (opParam.allReduceType != "sum" && opParam.allReduceType != "prod" && opParam.allReduceType != "max" &&
81	        opParam.allReduceType != "min") {
82	        ATB_LOG(ERROR) << "allReduceType is " << opParam.allReduceType
83	                       << "allReduceParam allReduceType must be one of the following sum, prod, max, min";
84	        return ERROR_INVALID_PARAM;
85	    }
86	    if (opParam.backend == "lccl" && opParam.allReduceType == "prod") {
87	        ATB_LOG(ERROR) << "allReduceType is " << opParam.allReduceType << "lccl not support prod ";
88	        return ERROR_INVALID_PARAM;
89	    }
90	    return NO_ERROR;
91	}
92	
93	template <> Status CreateOperation(const infer::AllReduceParam &opParam, Operation **operation)
94	{
95	    if (operation == nullptr) {
96	        return ERROR_INVALID_PARAM;
97	    }
98	    OP_PARAM_RSV_CHECK(opParam);
99	    if (CheckAllReduceParamValidity(opParam) != NO_ERROR) {
100	        return ERROR_INVALID_PARAM;
101	    }
102	    *operation = new (std::nothrow) AllReduceOperation(opParam);
103	    if (*operation == nullptr) {
104	        ATB_LOG(ERROR) << "failed to new operation";
105	        return ERROR_OUT_OF_HOST_MEMORY;
106	    }
107	    return NO_ERROR;
108	}
109	
110	AllReduceOperation::AllReduceOperation(const infer::AllReduceParam &param)
111	    : OperationBase("AllReduceOperation"), param_(param)
112	{
113	    if (param_.quantType == atb::infer::AllReduceParam::QUANT_TYPE_PER_TENSOR ||
114	        param_.quantType == atb::infer::AllReduceParam::QUANT_TYPE_PER_CHANNEL) {
115	        operationIr_ = atb::GetSingleton<AtbOperationIrCfg>().GetOperationIr("AllReduceOperationQuant");
116	    } else {
117	        operationIr_ = atb::GetSingleton<AtbOperationIrCfg>().GetOperationIr("AllReduceOperation");
118	    }
119	}
120	
121	AllReduceOperation::~AllReduceOperation() {}
122	
123	uint32_t AllReduceOperation::GetInputNum() const
124	{
125	    if (param_.quantType == atb::infer::AllReduceParam::QUANT_TYPE_PER_TENSOR ||
126	        param_.quantType == atb::infer::AllReduceParam::QUANT_TYPE_PER_CHANNEL) {
127	        return IN_TENSOR_NUM_WITH_QUANT;
128	    }
129	    return IN_TENSOR_NUM;
130	}
131	
132	uint32_t AllReduceOperation::GetOutputNum() const
133	{
134	    return OUT_TENSOR_NUM;
135	}
136	
137	Status AllReduceOperation::InferShapeImpl(const SVector<TensorDesc> &inTensorDescs,
138	                                          SVector<TensorDesc> &outTensorDescs) const
139	{
140	    outTensorDescs.at(0) = inTensorDescs.at(0);
141	    if (param_.quantType == atb::infer::AllReduceParam::QUANT_TYPE_PER_TENSOR ||
142	        param_.quantType == atb::infer::AllReduceParam::QUANT_TYPE_PER_CHANNEL) {
143	        outTensorDescs.at(0).dtype = param_.outDataType;
144	    }
145	    return NO_ERROR;
146	}
147	
148	Status AllReduceOperation::InferShapeCheckImpl(const SVector<TensorDesc> &inTensorDescs) const
149	{
150	    if (DtypeCheck(inTensorDescs.at(0)) != NO_ERROR) {
151	        return ERROR_INVALID_TENSOR_DTYPE;
152	    }
153	    int n = inTensorDescs.at(0).shape.dims[inTensorDescs.at(0).shape.dimNum - 1];
154	    if (inTensorDescs.size() > 1) {
155	        const int32_t offsetPosition = 1;
156	        const int32_t scalePosition = 2;
157	        return QuantShapeCheck(inTensorDescs.at(offsetPosition), inTensorDescs.at(scalePosition), n);
158	    }
159	    return NO_ERROR;
160	}
161	
162	Status AllReduceOperation::SetupCheckImpl(const SVector<Tensor> &inTensors, const SVector<Tensor> &outTensors) const
163	{
164	    if (DtypeCheck(inTensors.at(0).desc) != NO_ERROR) {
165	        return ERROR_INVALID_TENSOR_DTYPE;
166	    }
167	    ATB_LOG(DEBUG) << "outTensors size:" << outTensors.size();
168	    if (!TensorUtil::TensorShapeEqual(inTensors.at(0).desc.shape, outTensors.at(0).desc.shape)) {
169	        ATB_LOG(ERROR) << GetLogPrefix() << "intensor's shape and outtensor's shape should be same";
170	        return ERROR_INVALID_TENSOR_DIM;
171	    }
172	    int n = inTensors.at(0).desc.shape.dims[inTensors.at(0).desc.shape.dimNum - 1];
173	    if (inTensors.size() > 1) {
174	        const int32_t offsetPosition = 1; // 1: offsetPos
175	        const int32_t scalePosition = 2;  // 2: scalePos
176	        return QuantShapeCheck(inTensors.at(offsetPosition).desc, inTensors.at(scalePosition).desc, n);
177	    }
178	    return NO_ERROR;
179	}
180	
181	Status AllReduceOperation::DtypeCheck(const TensorDesc &inTensorDesc) const
182	{
183	    if (param_.backend == "lccl" && inTensorDesc.dtype == ACL_INT64) {
184	        ATB_LOG(ERROR) << "lccl allreduce is not support int64";
185	        return ERROR_INVALID_TENSOR_DTYPE;
186	    }
187	    if (param_.backend == "hccl" && GetSingleton<Config>().Is910A()) {
188	        if (inTensorDesc.dtype == ACL_INT16 || inTensorDesc.dtype == ACL_BF16) {
189	            ATB_LOG(ERROR) << "Atlas inference products hccl allreduce is not support int16 , bf16";
190	            return ERROR_INVALID_TENSOR_DTYPE;
191	        }
192	    }
193	    if (param_.backend == "hccl" && param_.allReduceType == "prod" && GetSingleton<Config>().Is910B()) {
194	        if (inTensorDesc.dtype == ACL_INT16 || inTensorDesc.dtype == ACL_BF16) {
195	            ATB_LOG(ERROR) << "Atlas A2 inference products hccl allreduce prod is not support int16 , bf16";
196	            return ERROR_INVALID_TENSOR_DTYPE;
197	        }
198	    }
199	    if (param_.backend == "hccl" && GetSingleton<Config>().Is310P()) {
200	        if (inTensorDesc.dtype == ACL_INT64 || inTensorDesc.dtype == ACL_BF16) {
201	            ATB_LOG(ERROR) << " Atlas 300I Duo inference products hccl allreduce is not support int64 , bf16";
202	            return ERROR_INVALID_TENSOR_DTYPE;
203	        }
204	        if (param_.allReduceType == "max" || param_.allReduceType == "min" || param_.allReduceType == "prod") {
205	            if (inTensorDesc.dtype == ACL_INT16) {
206	                ATB_LOG(ERROR)
207	                    << " Atlas 300I Duo inference products hccl allreducetype max,min,prod is not support int16";
208	                return ERROR_INVALID_TENSOR_DTYPE;
209	            }
210	        }
211	    }
212	    return NO_ERROR;
213	}
214	
215	Status AllReduceOperation::QuantShapeCheck(const TensorDesc &scale, const TensorDesc &offset, int n) const
216	{
217	    const uint64_t lastDimNum = 16;
218	    // input张量的最后一维(n)大小必须为16的整数倍
219	    if (n % lastDimNum != 0) {
220	        ATB_LOG(ERROR) << "quantType: " << param_.quantType << "input's last dimension or is not a multiple of 16";
221	        return ERROR_INVALID_TENSOR_DIM;
222	    }
223	    if (offset.shape.dimNum != 1 || offset.shape.dims[0] != 1) {
224	        ATB_LOG(ERROR) << "quantType: " << param_.quantType << "offset shape must be 1";
225	        return ERROR_INVALID_TENSOR_DIM;
226	    }
227	    const int32_t scaleMaxDimNum = 2;
228	    if (scale.shape.dimNum > scaleMaxDimNum) {
229	        ATB_LOG(ERROR) << "quantType: " << param_.quantType << "scale dimNum is not support";
230	        return ERROR_INVALID_TENSOR_DIM_NUM;
231	    }
232	    if (param_.quantType == atb::infer::AllReduceParam::QUANT_TYPE_PER_TENSOR) {
233	        if (scale.shape.dimNum != 1 || scale.shape.dims[0] != 1) {
234	            ATB_LOG(ERROR) << "quantType: " << param_.quantType << "scale shape must be 1";
235	            return ERROR_INVALID_TENSOR_DIM;
236	        }
237	    }
238	    if (param_.quantType == atb::infer::AllReduceParam::QUANT_TYPE_PER_CHANNEL) {
239	        if (n > 4194304) { // 4194304: 限制通道数最大值
240	            ATB_LOG(ERROR) << GetLogPrefix() << "quant channel num: " << n << " should be no more than 4194304(2^22)";
241	            return ERROR_INVALID_TENSOR_DIM;
242	        }
243	        // scale形状为[1,n]
244	        const int32_t scaleShapeNum = 2;
245	        if (scale.shape.dimNum == scaleShapeNum &&
246	            (scale.shape.dims[scale.shape.dimNum - 1] != n || scale.shape.dims[0] != 1)) {
247	            ATB_LOG(ERROR) << "quantType: " << param_.quantType
248	                           << " scale Num is 2  input dimension must be equal and scale shape must be [1,n]";
249	            return ERROR_INVALID_TENSOR_DIM;
250	        }
251	        // scale形状为[n]
252	        if (scale.shape.dimNum == 1 && scale.shape.dims[scale.shape.dimNum - 1] != n) {
253	            ATB_LOG(ERROR) << "quantType: " << param_.quantType << "scale Num is 1 scale shape must be n";
254	            return ERROR_INVALID_TENSOR_DIM;
255	        }
256	    }
257	    return NO_ERROR;
258	}
259	
260	std::shared_ptr<Runner> AllReduceOperation::CreateRunner(Context &context) const
261	{
262	    (void)context;
263	    if (param_.backend == "hccl") {
264	        if (param_.hcclComm == nullptr) {
265	            return std::make_shared<AllReduceHcclRunner>(param_, !param_.rankTableFile.empty());
266	        } else {
267	            return std::make_shared<AllReduceHcclRunner>(param_, param_.hcclComm);
268	        }
269	    } else if (param_.backend == "lccl") {
270	        return std::make_shared<AllReduceLcclRunner>(param_, context);
271	    }
272	    return std::shared_ptr<Runner>();
273	}
274	
275	nlohmann::json AllReduceOperation::GetParamJson() const
276	{
277	    return OpParamToJson(param_);
278	}
279	} // namespace atb
280

