45	        return false;
46	    }
47	    if (opParam.backend == "lccl" && !opParam.transpose &&
48	        std::string(socName).find("Ascend910_93") == std::string::npos) {
49	        ATB_LOG(ERROR) << "AllToAll lccl without transpose only supports Atlas 800T A3 or Atlas 900 A3 Superpod";
50	        return ERROR_INVALID_PARAM;
51	    }
52	    if (opParam.backend == "hccl") {
53	        if (!GetSingleton<Config>().Is910B() && std::string(socName).find("Ascend910_93") == std::string::npos) {
54	            ATB_LOG(ERROR) << "AllToAll hccl only supports Atlas 800I A2/A3 or Atlas 900 A3 Superpod";
55	            return ERROR_INVALID_PARAM;
56	        }
57	        if (opParam.transpose) {
58	            ATB_LOG(ERROR) << "AllToAll hccl doesn't support transpose";
59	            return ERROR_INVALID_PARAM;
60	        }
61	    }
62	    if (OperationUtil::DistributedInitCheck<infer::AllToAllParam>(opParam) != NO_ERROR) {
63	        ATB_LOG(ERROR) << "AllToAllOperation DistributedInitCheck failed";
64	        return ERROR_INVALID_PARAM;
65	    }
66	        if (opParam.backend == "lccl" && opParam.rankSize % 2 != 0) { // 2 : Even ranksize
67	        ATB_LOG(ERROR) << "AllToAll lccl only supports even ranksize";
68	        return ERROR_INVALID_PARAM;
69	    }
70	    *operation = new (std::nothrow) AllToAllOperation(opParam);
71	    if (*operation == nullptr) {
72	        ATB_LOG(ERROR) << "failed to new AllToAllOperation";
73	        return ERROR_OUT_OF_HOST_MEMORY;
74	    }
75	    return NO_ERROR;
76	}
