100	Status AllToAllOperation::InferShapeCheckImpl(const SVector<TensorDesc> &inTensorDescs) const
101	{
102	    if (!param_.transpose) {
103	        return NO_ERROR;
104	    }
105	    if (inTensorDescs.at(0).shape.dimNum != TRANSPOSE_IN_TENSOR_DIM_NUM) { // 2: transpose only support dimNum
106	        ATB_LOG(ERROR) << "inTensor[0] dimNum should be " << TRANSPOSE_IN_TENSOR_DIM_NUM
107	                       << ", but got: " << inTensorDescs.at(0).shape.dimNum;
108	        return ERROR_INVALID_TENSOR_DIM_NUM;
109	    }
110	    if (inTensorDescs.at(0).shape.dims[1] % param_.rankSize != 0) {
111	        ATB_LOG(ERROR) << "intensors[0].dims[0] must be an integer multiple of ranksize but got dims[0]: "
112	                       << inTensorDescs.at(0).shape.dims[1] << ", rankSize: " << param_.rankSize;
113	        return ERROR_INVALID_TENSOR_DIM;
114	    }
115	    int64_t wSize = inTensorDescs.at(0).shape.dims[TRANSPOSE_IN_TENSOR_DIM_NUM - 1] *
116	                    static_cast<int64_t>(sizeof(inTensorDescs.at(0).dtype));
117	    if (wSize / param_.rankSize >= MAX_W_SIZE) {
118	        ATB_LOG(ERROR) << "intensors[0].dims[1] / rankSize must be no greater than 90K, but got bytes: " << wSize;
119	        return ERROR_INVALID_TENSOR_DIM;
120	    }
121	    uint64_t tensorSize = Utils::GetTensorSize(inTensorDescs.at(0));
122	    if (tensorSize > MAX_TENSOR_SIZE) {
123	        ATB_LOG(ERROR) << "intensors[0] total tensor size must be no greater than 190MB, but got bytes: " << tensorSize;
124	        return ERROR_INVALID_TENSOR_DIM;
125	    }
126	    return NO_ERROR;
127	}
