131	{
132	    outTensorDescs.at(0) = inTensorDescs.at(0);
133	    if (param_.backend == "lccl" && param_.transpose) {
134	        outTensorDescs.at(0).shape.dims[0] = inTensorDescs.at(0).shape.dims[0] * param_.rankSize;
135	        outTensorDescs.at(0).shape.dims[1] = inTensorDescs.at(0).shape.dims[1] / param_.rankSize;
136	    }
137	    return 0;
