143	    OperationUtil::InTensorsToInTensorDescs(inTensors, inTensorDescs);
144	    Status st = InferShapeCheckImpl(inTensorDescs);
145	    if (st != NO_ERROR) {
146	        return st;
147	    }
148	    if (!param_.transpose && !TensorUtil::TensorDescEqual(inTensors.at(0).desc, outTensors.at(0).desc)) {
149	        ATB_LOG(ERROR) << GetLogPrefix() << "intensor desc and outtensor desc should be same";
150	        return ERROR_INVALID_TENSOR_DIM;
151	    }
152	    if (param_.transpose) {
153	        if (inTensors.at(0).desc.shape.dimNum != TRANSPOSE_IN_TENSOR_DIM_NUM) {
154	            ATB_LOG(ERROR) << "invalid inTensor dimNum, should be 2, but got inTensors[0] dimNum: "
155	                           << inTensors.at(0).desc.shape.dimNum;
156	            return ERROR_INVALID_TENSOR_DIM_NUM;
157	        }
158	        if (outTensors.at(0).desc.shape.dimNum != TRANSPOSE_IN_TENSOR_DIM_NUM) {
159	            ATB_LOG(ERROR) << "invalid outTensor dimNum, should be 2, but got outTensors[0] dimNum: "
160	                           << outTensors.at(0).desc.shape.dimNum;
161	            return ERROR_INVALID_TENSOR_DIM_NUM;
162	        }
163	        if (outTensors.at(0).desc.shape.dims[0] != inTensors.at(0).desc.shape.dims[0] * param_.rankSize) {
164	            ATB_LOG(ERROR) << "invalid outTensor dims[0] should be intensors[0].dims[0], * rankSize, i.e. "
165	                           << inTensors.at(0).desc.shape.dims[0] << " * " << param_.rankSize << ", but got "
166	                           << outTensors.at(0).desc.shape.dims[0];
167	            return ERROR_INVALID_TENSOR_DIM;
168	        }
169	        if (outTensors.at(0).desc.shape.dims[1] * param_.rankSize != inTensors.at(0).desc.shape.dims[1]) {
170	            ATB_LOG(ERROR) << "invalid outTensor dims[1], should be intensors[0].dims[1]/rankSize, i.e. "
171	                           << inTensors.at(0).desc.shape.dims[1] << " / " << param_.rankSize << ", but got "
172	                           << outTensors.at(0).desc.shape.dims[1];
173	            return ERROR_INVALID_TENSOR_DIM;
174	        }
175	    }
176	    return NO_ERROR;
