162	bool HcclRunner::CreateHcclRootInfo()
163	{
164	    std::string shmName = "hcclShareMem" + commDomain_;
165	    Mki::ShareMemory shm(shmName, sizeof(atb::CommInitInfo) + rankSize_ * sizeof(bool));
166	    auto *shmInfo = static_cast<atb::CommInitInfo *>(shm.GetShm());
167	    if (!shmInfo) {
168	        ATB_LOG(ERROR) << GetLogPrefix() << "create share memory fail, rank:" << rank_;
169	        return false;
170	    }
171	
172	    // 主进程通过HcclGetRootInfo获取到hcclRootInfo_(包含HostIP信息), 写到共享内存，其他进程读取RoortInfo
173	    // 等所有的进程都准备好时，再一起往下执行CreateHcclComm
174	    ATB_LOG(INFO) << GetLogPrefix() << "create share memory success, rank:" << rank_;
175	    if (rank_ == rankRoot_) {
176	        auto ret = HcclGetRootInfo(&hcclRootInfo_);
177	        if (ret != HCCL_SUCCESS) {
178	            ATB_LOG(ERROR) << GetLogPrefix() << "HcclGetRootInfo fail, error:" << ret << ", rank:" << rank_;
179	            return false;
180	        }
181	        ATB_LOG(INFO) << GetLogPrefix() << "HcclGetRootInfo success, write to share memory";
182	        ShmSetHcclRootInfo(shm, *shmInfo);
183	    } else {
184	        ATB_LOG(INFO) << GetLogPrefix() << "get root info from share memory";
185	        ShmGetHcclRootInfo(shm, *shmInfo);
186	    }
187	
188	    return ShmBarrier(shm, *shmInfo);
189	}
190	
191	void HcclRunner::ShmGetHcclRootInfo(Mki::ShareMemory &shm, const CommInitInfo &shmInfo)
192	{
193	    bool commIdReady = false;
194	    while (true) {
195	        shm.SemLock();
196	        if (shmInfo.signal != 0) {
197	            hcclRootInfo_ = shmInfo.hcclRootInfo;
198	            commIdReady = true;
199	        }
200	        shm.SemUnLock();
201	        if (commIdReady) {
202	            break;
203	        }
204	    }
205	}
206	
207	void HcclRunner::ShmSetHcclRootInfo(Mki::ShareMemory &shm, CommInitInfo &shmInfo)
208	{
209	    shm.SemLock();
210	    shmInfo.hcclRootInfo = hcclRootInfo_;
211	    shmInfo.signal = 1;
212	    shm.SemUnLock();
213	}
214	
215	void HcclRunner::ShmSetReady(Mki::ShareMemory &shm, CommInitInfo &shmInfo) const
216	{
217	    shm.SemLock();
218	    shmInfo.barrier[rank_] = true;
219	    shm.SemUnLock();
220	}
221	
222	bool HcclRunner::ShmBarrier(Mki::ShareMemory &shm, CommInitInfo &shmInfo)
223	{
224	    ATB_LOG(INFO) << GetLogPrefix() << "barrier start, rank:" << rank_;
225	    ShmSetReady(shm, shmInfo);
226	
227	    ATB_LOG(INFO) << GetLogPrefix() << "check all ready start";
228	    const double timeout = 600; // 600: 10 minutes timeout
229	    time_t startTime = time(nullptr);
230	    while (true) {
231	        time_t currentTime = time(nullptr);
232	        if (difftime(currentTime, startTime) > timeout) {
233	            ATB_LOG(ERROR) << GetLogPrefix() << "barrier fail, check all ready timeout";
234	            return false;
235	        }
236	
237	        bool allReady = true;
238	        shm.SemLock();
239	        for (int i = 0; i < rankSize_; i++) {
240	            if (!shmInfo.barrier[i]) {
241	                allReady = false;
242	                break;
243	            }
244	        }
245	        shm.SemUnLock();
246	        if (allReady) {
247	            ATB_LOG(INFO) << GetLogPrefix() << "check all ready success";
248	            break;
249	        }
250	    }
251	
252	    ATB_LOG(INFO) << GetLogPrefix() << "barrier success, rank:" << rank_;
253	    return true;
254	}
255	
256	static bool IsHcclRunnerTensorValid(const SVector<Tensor> &tensors)
257	{
258	    for (const auto &tensor : tensors) {
259	        if (!tensor.deviceData) {
260	            ATB_LOG(ERROR) << "tensor devoce is null";
261	            return false;
262	        }
263	    }
264	    return true;
265	}
