267	Status HcclRunner::ExecuteImpl(RunnerVariantPack &runnerVariantPack)
268	{
269	    if (!hcclComm_) {
270	        return ERROR_COMM_EMPTY;
271	    }
272	
273	    if (!IsHcclRunnerTensorValid(runnerVariantPack.inTensors) ||
274	        !IsHcclRunnerTensorValid(runnerVariantPack.outTensors)) {
275	        return ERROR_INVALID_PARAM;
276	    }
277	    return ErrorType::NO_ERROR;
278	}
